#!/usr/bin/env python3
"""Serialize the five individually assessed directions already in directions.md."""
import json
from pathlib import Path
P=Path(__file__).parent
D=[]
def add(n,title,interest,progress,items,claims,problems,goal,known,step):
 D.append(dict(id=f'D-SA23-root-{n:02}',title=title,interest=interest,feasible_progress_in_one_run=progress,items=[f'SA23-{i}'for i in items],claims=[f'C-SA23-root-{i:03}'for i in claims],problems=[f'MP-SA23-root-{i:02}'for i in problems],would_establish=goal,known=known,first_step=step,development='None; this is a task specification, not a result of the consolidation.'))
add(1,'Selected-family versus all-bundle universal Chern rings',5,4,[25,32,33,41],[25,27,32,33],[4,6,7],'A comparison map with exact hypotheses for an isomorphism or a surviving torsion kernel.','SGA6 V6.14 and Mackall2020 Proposition2.1/Theorem4.1 concern specified universal problems; the selected-family construction has not been identified with them.','Write the two representing categories and their rank, operation and pullback relations side by side; test the comparison on the projective plane using all geometric classes.')
add(2,'An integral supported lambda filtration',5,3,list(range(48,55))+[58],[45,50,52,53,58],[8,10,11,13],'A definition of supported nonunital operations with a comparison target that separates supported cycles from their ambient image.','Rational localized Chern characters are established; a literal supported cycle-to-ambient-image identification loses information.','Fix a regular noetherian affine scheme and one principal closed support, then state the unitization and exact-category operations before asking for a Chow comparison.')
add(3,'Integral symmetric-tensor descent',4,4,[21,22,23,24],[21,22,23,24],[3],'A checked construction of exterior operations on the intended integral Grothendieck group, beyond the local orbit decomposition.','The local symmetric-tensor and Young-subgroup calculations are checked; the revised exact category and descent conventions remain to be specified.','Recover the exact category and locality convention from scans17–19, then prove or refute compatibility with one short exact sequence and descent.')
add(4,'Global infinitesimal-neighborhood comparison',3,3,[42,43,44,45,50],[42,43,45,50],[8],'A global noetherian statement of filtered full-faithfulness with specified morphisms and support.','The affine finite-object argument is checked. The manuscript assertion itself is not marked as an open question; the task is a present-run global comparison.','Choose a finite affine cover of a separated noetherian scheme and compare the filtered Ext calculation with its Cech/local-to-global sequence.')
add(5,'The exact bimodule polarization convention',2,4,[76],[76,79,81],[2],'An editorial determination of the final remark under its original scalar-action axioms.','Only a conditional counterexample under modern conventional axioms is established. The preceding typed conditions are not supplied.','Obtain conditions(1)–(4), then check the placement of scalar actions and the use of centrality in formula(14).')
(P/'directions.json').write_text(json.dumps(D,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({'directions':len(D),'source':'directions.md, individually authored before serialization'}))
